fn project(value:&SemioObjectSnapshot)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioObjectSnapshot, semio_framework_value::ValueError>{SemioObjectSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_object_placement_typed_handles_optional_presence_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&restored),<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&restored),<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&snapshot));for mask in 0..8{let mut value=fixture();if mask&1==0{value.brep=None;}if mask&2==0{value.mesh=None;}if mask&4==0{value.properties=None;}assert_eq!(restore(&project(&value)).unwrap(),value);}assert_eq!(restore(&project(&SemioObjectSnapshot::default())).unwrap(),SemioObjectSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_object_rejects_child_reference_identity_shape_and_limits(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_object_mesh_child").unwrap().rows[0].values[3]=SqliteValue::Integer(999),1=>db.table_mut("semio_object_reference").unwrap().rows[1].values[2]=SqliteValue::Text("foreign.artifact".into()),2=>db.table_mut("semio_object_reference").unwrap().rows[1].values[4]=SqliteValue::Text("brep".into()),3=>db.table_mut("semio_object_mesh_child").unwrap().rows[0].values[1]=SqliteValue::Integer(999),_=>{db.table_mut("semio_object_mesh_child").unwrap().rows.clear();}}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioObjectSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_object_independent_reference_join_and_transform_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT child_id,artifact_id,artifact_kind,standard,subset FROM semio_object_mesh_child JOIN semio_object_reference ON target_reference_id=semio_object_reference.id').get();if(r.child_id!=='mesh-owned'||r.artifact_id!==r.child_id||r.artifact_kind!=='s.stdio.semio'||r.standard!=='v1'||r.subset!=='mesh')throw Error('typed child');db.query('UPDATE semio_object_document SET translation_x=9.25,translation_x_ieee754_bits=4621396905123905536').run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.transform.translation.x=9.25;assert_eq!(restored,expected);}

